<script setup lang="ts">
import {t as tr} from "../i18n";
import {ref,computed,onMounted,onUnmounted,watch} from 'vue';import {businessApi,useBusinessStore} from '../stores/business';import {useSessionStore} from '../stores/session';import {useRunStore} from '../stores/run';import type {RoomSummary} from '@shared/mobile';import type {BusinessResult,NativeContext} from '@shared/business';import type {Target} from '@shared/labops-targets.js';import {PERIODS} from '@shared/periods';import BusinessPlanCard from '../components/BusinessPlanCard.vue';import UiIcon from '../components/UiIcon.vue';import AsyncState from './AsyncState.vue';import {useVisibleRefresh} from '../composables/useVisibleRefresh';import {useCollection} from '../composables/useCollection';import {roomFreeForPeriod,compareRoomSelection} from './room-view';import {usePullRefreshRegistration} from './gestures';import {useModal} from '../composables/useModal';import {visionAvailable,probeVisionModule} from '../vision-ui';
const props=defineProps<{roomId?:string;action?:string}>(),emit=defineEmits<{navigate:[Target]}>(),business=useBusinessStore(),session=useSessionStore(),run=useRunStore(),rooms=ref<RoomSummary[]>([]),loading=ref(true),error=ref(''),query=ref(''),filter=ref('all'),date=ref(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai'}).format(new Date())),period=ref('am1'),workflow=ref<BusinessResult>(),detailTab=ref('overview'),comparing=ref(false),compareIds=ref<string[]>([]),filterOpen=ref(false),actionOpen=ref(false);let generation=0;
const filterNames:Record<string,string>={all:'全部',favorites:'收藏',free:'本节空闲',classes:'本节有课',suspended:'停用'};
const favorites=useCollection('rooms',()=>business.profile?business.profile.identity+':'+business.profile.username:'');
const selected=computed(()=>rooms.value.find(r=>r.roomId===props.roomId)),compareRooms=computed(()=>compareIds.value.map(id=>rooms.value.find(r=>r.roomId===id)).filter((r):r is RoomSummary=>Boolean(r)));
const list=computed(()=>rooms.value.filter(r=>(!query.value||r.roomName.toLowerCase().includes(query.value.toLowerCase())||r.location.toLowerCase().includes(query.value.toLowerCase()))&&(filter.value==='all'||filter.value==='favorites'&&favorites.ids.value.includes(r.roomId)||filter.value==='open'&&r.recordedDoorState==='open'||filter.value==='suspended'&&r.serviceState==='suspended'||filter.value==='inuse'&&r.occupancy.value!==null&&r.occupancy.value>0||filter.value==='classes'&&r.schedule.some(l=>l.periodKey===period.value)||filter.value==='free'&&roomFreeForPeriod(r,period.value))).slice().sort((a,b)=>Number(favorites.ids.value.includes(b.roomId))-Number(favorites.ids.value.includes(a.roomId))||a.roomName.localeCompare(b.roomName,'zh-CN',{numeric:true})));
const labels:Record<string,string>={open:'登记开放',closed:'登记关闭',unknown:'未知',normal:'服务正常',suspended:'服务停用',occupied:'有排课',no_scheduled_class:'无排课',active:'档案开放',inactive:'档案停用',in_cabinet:'在钥匙柜',borrowed:'登记借用',handover:'待交接'};
const periodLabel=(key:string)=>PERIODS.find(p=>p.key===key)?.label||key,lessonCount=(r:RoomSummary)=>r.scheduleState==='unknown'?'未知':r.schedule.filter(l=>l.periodKey===period.value).length,activeIssues=(r:RoomSummary)=>r.related.issues.filter(i=>!['closed','cancelled'].includes(i.status));
const activeFilterLabel=computed(()=>tr(filterNames[filter.value]||filter.value));
const filterChoices=computed(()=>[{id:'all',name:tr('全部'),count:rooms.value.length},{id:'favorites',name:tr('收藏'),count:rooms.value.filter(r=>favorites.ids.value.includes(r.roomId)).length},{id:'free',name:tr('本节空闲'),count:rooms.value.filter(r=>roomFreeForPeriod(r,period.value)).length},{id:'classes',name:tr('本节有课'),count:rooms.value.filter(r=>r.schedule.some(l=>l.periodKey===period.value)).length},{id:'suspended',name:tr('停用'),count:rooms.value.filter(r=>r.serviceState==='suspended').length}]);
useModal(filterOpen,'.room-filter-sheet');useModal(actionOpen,'.room-action-sheet');
function toggleCompare(){comparing.value=!comparing.value;compareIds.value=[];}
function chooseFilter(id:string){filter.value=id;filterOpen.value=false;}
function clearFilter(){filter.value='all';filterOpen.value=false;}
function selectRoom(id:string){if(comparing.value){compare(id);return;}emit('navigate',{view:'room',roomId:id});}
/** 详情页只留一个主操作，其余收进“更多办理”；按身份决定主操作 */
const primaryAction=computed(()=>business.profile?.identity==='admin'
 ?{label:tr('报修与工单'),icon:'work',target:{view:'room',roomId:props.roomId,action:'issues'} as Target}
 :{label:tr('检查与交接'),icon:'file',target:{view:'room',roomId:props.roomId,action:'duty'} as Target});
const secondaryActions=computed(()=>{const list=[{label:tr('检查与交接'),target:{view:'room',roomId:props.roomId,action:'duty'} as Target},{label:tr('报修与工单'),target:{view:'room',roomId:props.roomId,action:'issues'} as Target}];if(business.profile?.identity==='admin')list.push({label:tr('指定日期调课'),target:{view:'room',roomId:props.roomId,action:'schedule'} as Target},{label:tr('停用与撤销'),target:{view:'room',roomId:props.roomId,action:'closures'} as Target});list.push({label:tr('证据与资料'),target:{view:'evidence',roomId:props.roomId} as Target});return list.filter(item=>item.label!==primaryAction.value.label);});
function runAction(target:Target){actionOpen.value=false;emit('navigate',target);}
async function refresh(){const epoch=++generation,scope=business.scopeKey;try{const q=new URLSearchParams({date:date.value,...(props.roomId?{roomId:props.roomId}:{})}),result=await businessApi<{rooms:RoomSummary[]}>('proxy/room-summaries?'+q);if(epoch===generation&&scope===business.scopeKey){rooms.value=result.rooms;error.value='';compareIds.value=compareIds.value.filter(id=>rooms.value.some(r=>r.roomId===id));}}catch(e){if(epoch===generation)error.value=(e as Error).message;}finally{if(epoch===generation)loading.value=false;}}
async function openWorkflow(view:string){if(run.inputLocked)return;const scope=business.scopeKey;try{const context=await businessApi<NativeContext>('proxy/context');if(scope!==business.scopeKey)return;session.startDraft();workflow.value={summary:'从实验室详情进入办理',view:view as BusinessResult['view'],planId:null,context,candidates:[],date:date.value,initialRoomId:props.roomId,scopeKey:scope,source:'主系统授权业务接口',queriedAt:new Date().toISOString(),workbenchUrl:'/operations.html?bridge=1'};}catch(e){error.value=(e as Error).message;}}
async function enter(){workflow.value=undefined;loading.value=true;await refresh();if(props.action&&selected.value)await openWorkflow(props.action);}
function compare(id:string){compareIds.value=compareRoomSelection(compareIds.value,id);}
onMounted(()=>{probeVisionModule();enter();});watch(()=>[props.roomId,props.action],()=>{detailTab.value='overview';void enter();});watch(date,refresh);watch(()=>business.scopeKey,()=>{generation++;rooms.value=[];workflow.value=undefined;compareIds.value=[];void enter();});onUnmounted(()=>generation++);useVisibleRefresh(refresh,()=>!workflow.value);usePullRefreshRegistration('rooms',refresh);
</script>
<template><AsyncState :loading="loading" :error="error" @retry="refresh">
<template v-if="!roomId">
<div class="room-toolbar"><label class="room-search"><UiIcon name="search"/><input id="room-search" v-model="query" type="search" :placeholder="tr('名称 / 位置')" :aria-label="tr('搜索实验室')"></label><button class="room-tool" :aria-label="tr('筛选')" :aria-pressed="filter!=='all'" @click="filterOpen=true"><UiIcon name="settings"/><span v-if="filter!=='all'" class="room-tool-dot" aria-hidden="true"></span></button><button v-if="visionAvailable" class="room-tool" :aria-label="tr('实验室监控')" @click="emit('navigate',{view:'vision'})"><UiIcon name="camera"/></button><button class="room-tool" :aria-pressed="comparing" :aria-label="tr('对比')" @click="toggleCompare"><UiIcon name="compare"/></button></div>
<div class="room-scope"><label>{{tr("日期")}}<input v-model="date" type="date" :aria-label="tr('查询日期')"></label><label>{{tr("节次")}}<select v-model="period" :aria-label="tr('查询节次')"><option v-for="p in PERIODS" :key="p.key" :value="p.key">{{tr(p.label)}}</option></select></label></div>
<p v-if="filter!=='all'" class="room-filter-note">{{activeFilterLabel}} · <button class="room-filter-reset" @click="filter='all'">{{tr('全部')}}</button></p>
<div class="room-list-summary"><span>{{list.length}} {{tr("间实验室")}}</span><span>{{tr("开放")}} {{rooms.filter(r=>r.recordedDoorState==='open').length}} {{tr("· 停用")}} {{rooms.filter(r=>r.serviceState==='suspended').length}} {{tr("· 收藏")}} {{rooms.filter(r=>favorites.ids.value.includes(r.roomId)).length}}</span></div>
<p v-if="filter==='free'" class="room-filter-note">{{tr("仅显示本节无排课且服务正常、登记开放的房间。")}}</p>
<section v-if="comparing" class="room-compare mobile-section" :aria-label="tr('实验室对比')"><header class="mobile-section-head"><h3>{{tr("房间对比")}} {{compareRooms.length}}/2</h3><button @click="compareIds=[]">{{tr("清空")}}</button></header><p v-if="!compareRooms.length" class="mobile-empty">{{tr("在卡片中选择最多两间房间")}}</p><table v-else><caption>{{date}} · {{periodLabel(period)}}</caption><thead><tr><th>{{tr("项目")}}</th><th v-for="r in compareRooms" :key="r.roomId">{{r.roomName}}</th></tr></thead><tbody><tr><th>{{tr("容量")}}</th><td v-for="r in compareRooms" :key="r.roomId">{{tr(r.capacity??'未知')}}</td></tr><tr><th>{{tr("登记 / 服务")}}</th><td v-for="r in compareRooms" :key="r.roomId">{{tr(labels[r.recordedDoorState])}} / {{tr(labels[r.serviceState])}}</td></tr><tr><th>{{tr("有效签到记录")}}</th><td v-for="r in compareRooms" :key="r.roomId">{{tr(r.occupancy.value??'未知')}}</td></tr><tr><th>{{tr("本节排课记录")}}</th><td v-for="r in compareRooms" :key="r.roomId">{{lessonCount(r)}}</td></tr><tr><th>{{tr("设备")}}</th><td v-for="r in compareRooms" :key="r.roomId">{{r.equipment?.join('、')||tr('未知')}}</td></tr><tr><th>{{tr("钥匙登记")}}</th><td v-for="r in compareRooms" :key="r.roomId">{{tr(labels[r.key.state])}} · {{r.key.location||tr('未知')}}</td></tr><tr><th>{{tr("未关闭工单")}}</th><td v-for="r in compareRooms" :key="r.roomId">{{activeIssues(r).length}}</td></tr></tbody></table><details v-if="compareRooms.length"><summary>{{tr("查询依据")}}</summary><p v-for="r in compareRooms" :key="r.roomId">{{r.roomName}} · {{r.queriedAt}} · {{r.sourceRevision.slice(0,12)}} · {{r.occupancy.note}}</p></details></section>
<p v-if="!list.length" class="mobile-state">{{tr("没有符合条件的实验室。")}}</p>
<div class="room-list"><article v-for="r in list" :key="r.roomId" class="room-row" :class="{'is-suspended':r.serviceState==='suspended','is-selected':compareIds.includes(r.roomId)}"><button class="room-row-main" :aria-pressed="comparing?compareIds.includes(r.roomId):undefined" @click="selectRoom(r.roomId)"><span v-if="comparing" class="room-row-check" aria-hidden="true">{{compareIds.includes(r.roomId)?'✓':'○'}}</span><span class="room-row-body"><b>{{r.roomName}}</b><small>{{tr(r.location||'位置未知')}}</small><span class="room-row-facts"><span>{{tr("签到")}} <strong>{{r.occupancy.value??'?'}}</strong></span><span>{{tr("容量")}} <strong>{{r.capacity??'?'}}</strong></span><span>{{lessonCount(r)==='未知'?tr('课表未知'):tr('本节')+' '+lessonCount(r)+' '+tr('条课')}}</span></span><span class="room-row-status"><span>{{tr(labels[r.recordedDoorState])}}</span><span :class="{'is-warning':r.serviceState==='suspended'}">{{tr(labels[r.serviceState])}}</span></span></span><UiIcon v-if="!comparing" name="chevron" class="room-row-chevron"/></button><button v-if="!comparing" class="room-favorite room-row-fav" :aria-label="(favorites.ids.value.includes(r.roomId)?'取消收藏':'收藏')+' '+r.roomName" :aria-pressed="favorites.ids.value.includes(r.roomId)" @click="favorites.toggle(r.roomId)"><UiIcon name="star" :size="14"/></button></article></div>
<div v-if="filterOpen" class="mobile-sheet-mask" @click.self="filterOpen=false"><section class="mobile-sheet room-filter-sheet" role="dialog" aria-modal="true"><h2>{{tr('实验室筛选')}}</h2><p>{{tr('按登记、服务与排课筛选。')}}</p><button v-for="f in filterChoices" :key="f.id" :aria-pressed="filter===f.id" @click="chooseFilter(f.id)"><span>{{f.name}}</span><span>{{f.count}}</span></button><button class="room-filter-clear" @click="clearFilter">{{tr('全部')}}</button><button @click="filterOpen=false">{{tr('关闭')}}</button></section></div>
</template>
<template v-else-if="selected"><template v-if="!workflow">
<div class="mobile-greeting room-detail-title"><div><h2>{{selected.roomName}}</h2><span>{{selected.location||tr('位置未知')}}</span></div><button :aria-label="(favorites.ids.value.includes(selected.roomId)?'取消收藏':'收藏')+' '+selected.roomName" :aria-pressed="favorites.ids.value.includes(selected.roomId)" @click="favorites.toggle(selected.roomId)"><UiIcon name="star"/></button></div>
<nav class="room-detail-tabs" :aria-label="tr('房间详情')" role="tablist"><button v-for="t in [{id:'overview',label:'概览'},{id:'schedule',label:'课程'},{id:'work',label:'工作'},{id:'key',label:'钥匙'}]" :key="t.id" role="tab" :aria-selected="detailTab===t.id" @click="detailTab=t.id">{{tr(t.label)}}</button></nav>
<section v-if="detailTab==='overview'" class="room-overview"><div class="room-fact-grid"><div><span>{{tr("人员开放登记")}}</span><b>{{tr(labels[selected.recordedDoorState])}}</b></div><div><span>{{tr("服务状态")}}</span><b :class="{'is-warning':selected.serviceState==='suspended'}">{{tr(labels[selected.serviceState])}}</b></div><div><span>{{tr("有效签到记录")}}</span><b>{{tr(selected.occupancy.value??'未知')}}<small v-if="selected.occupancy.value!==null"> {{tr("条")}}</small></b></div><div><span>{{tr("容量")}}</span><b>{{tr(selected.capacity??'未知')}}</b></div><div><span>{{tr("教学占用")}}</span><b>{{labels[selected.scheduleState]}}</b></div><div><span>{{tr("数据质量")}}</span><b>{{tr(selected.occupancy.quality==='valid'?'可用':selected.occupancy.quality==='partial'?'待核实':'未知')}}</b></div></div><div v-for="c in selected.closures" :key="c.id" class="mobile-warning">{{c.startDate}} {{tr("至")}} {{c.endDate}} · {{c.reason}}</div><section class="mobile-section room-primary-action"><header class="mobile-section-head"><h3>{{tr('房间办理')}}</h3></header><button class="mobile-primary" :disabled="run.inputLocked" @click="emit('navigate',primaryAction.target)"><UiIcon :name="primaryAction.icon"/>{{primaryAction.label}}</button><button class="room-more-action" @click="actionOpen=true">{{tr('更多办理')}}</button></section><section class="mobile-section"><header class="mobile-section-head"><h3>{{tr("相关工作")}}</h3><button @click="detailTab='work'">{{tr("查看")}}</button></header><div class="room-related-counts"><span>{{tr("工单")}} {{activeIssues(selected).length}}</span><span>{{tr("班次")}} {{selected.related.shifts.length}}</span><span>{{tr("遗留")}} {{selected.related.items.length}}</span></div></section></section>
<section v-else-if="detailTab==='schedule'" class="mobile-section"><h3>{{tr("指定日期课程")}}</h3><label>{{tr("上海日期")}}<input v-model="date" type="date"></label><article v-for="t in selected.schedule" :key="t.id" class="room-lesson"><b>{{t.courseName}}</b><span>{{periodLabel(t.periodKey)}} · {{(t.classNames||[t.className]).join('、')}}</span><small>{{t.id}}</small></article><p v-if="!selected.schedule.length" class="mobile-empty">{{tr(selected.scheduleState==='unknown'?'课程情况未知':'该日没有已排课程')}}</p></section>
<section v-else-if="detailTab==='key'" class="mobile-section"><h3>{{tr("钥匙登记")}}</h3><dl class="mobile-facts"><dt>{{tr("状态")}}</dt><dd>{{tr(labels[selected.key.state])}}</dd><dt>{{tr("位置")}}</dt><dd>{{tr(selected.key.location||'未知')}}</dd><dt>{{tr("借用人")}}</dt><dd>{{tr(selected.key.holder||'未登记')}}</dd><dt>{{tr("登记时间")}}</dt><dd>{{tr(selected.key.recordedAt||'未知')}}</dd></dl><p>{{selected.key.note}}</p></section>
<section v-else class="mobile-section"><h3>{{tr("可见的相关业务")}}</h3><button v-for="i in selected.related.issues" :key="i.id" class="mobile-row" @click="emit('navigate',{view:'room',roomId,action:'issues'})"><b>{{i.description}}<span class="mobile-pill">{{i.status}}</span></b><small>{{tr("工单")}} {{i.id}}</small></button><button v-for="s in selected.related.shifts" :key="s.id" class="mobile-row" @click="emit('navigate',{view:'room',roomId,action:'duty'})">{{tr("班次")}} {{s.id}} · {{periodLabel(s.periodKey)}} · {{s.userId}}</button><button v-for="h in selected.related.handovers" :key="h.id" class="mobile-row" @click="emit('navigate',{view:'room',roomId,action:'duty'})">{{tr("交接")}} {{h.id}} · {{h.status}}</button><details v-for="i in selected.related.inspections" :key="i.id" class="room-record"><summary>{{tr("检查")}} {{i.id}} · {{i.date}}</summary><p v-for="(c,index) in i.checklist" :key="index">{{c.label}} · {{tr(c.state==='done'?'已确认':c.state==='abnormal'?'异常':'未确认')}}</p><p v-if="i.note">{{i.note}}</p></details><article v-for="i in selected.related.items" :key="i.id" class="room-record"><b>{{i.description}}</b><p>{{tr("遗留")}} {{i.id}} · {{i.state}} {{tr("· 截止")}} {{tr(i.deadline||'未设置')}}</p></article><p v-if="!selected.related.issues.length&&!selected.related.shifts.length&&!selected.related.handovers.length&&!selected.related.inspections.length&&!selected.related.items.length" class="mobile-empty">{{tr("当前范围没有相关记录")}}</p></section>
<details class="mobile-source"><summary>{{tr("数据依据与记录口径")}}</summary><p>{{tr("档案")}} {{labels[selected.registryStatus]||selected.registryStatus}} · {{tr(selected.doorRecordedAt||'登记时间未知')}}</p><p>{{selected.doorNote}} · {{selected.occupancy.note}}</p><p>{{tr("查询")}} {{selected.queriedAt}} {{tr("· 版本")}} {{selected.sourceRevision.slice(0,12)}}</p></details>
<div v-if="actionOpen" class="mobile-sheet-mask" @click.self="actionOpen=false"><section class="mobile-sheet room-filter-sheet room-action-sheet" role="dialog" aria-modal="true"><h2>{{tr('更多办理')}}</h2><p>{{tr('按房间与身份可用的办理入口。')}}</p><button v-for="item in secondaryActions" :key="item.label" :disabled="run.inputLocked" @click="runAction(item.target)">{{item.label}}</button><button @click="actionOpen=false">{{tr('关闭')}}</button></section></div></template><template v-else><BusinessPlanCard :key="roomId+':'+workflow.view" :result="workflow" :card-id="'mobile-room:'+roomId+':'+workflow.view" :readonly="run.inputLocked"/></template></template><p v-else class="mobile-state">{{tr("未找到当前可见的实验室")}}</p>
</AsyncState></template>
